import java.io.UnsupportedEncodingException;
import java.net.URLEncoder;
import java.util.List;

public String createQueryString(List<String> fieldNames) throws UnsupportedEncodingException {
    StringBuilder queryString = new StringBuilder();
    for (String fieldName : fieldNames) {
        queryString.append(URLEncoder.encode(fieldName, "UTF-8")).append("=");
        // You can append a value here if needed, e.g., URLEncoder.encode(value, "UTF-8")
        queryString.append("&");
    }
    if (queryString.length() > 0) {
        queryString.deleteCharAt(queryString.length() - 1); // Remove the last '&'
    }
    return queryString.toString();
}
```

This method constructs a query string by encoding each field name and appending it to the `StringBuilder`. Make sure to handle the values appropriately if you want to include them in the query string.

